module legacy_buffers;
fn file_read_bytes(value:i64) -> i64 { return value+1; }
fn file_write_bytes(value:str) -> str { return value; }
fn bytes(value:i64) -> i64 { return value; }
fn identity<T:wire>(value:T) -> T { return unwrap(decode_json<T>(encode_json(value))); }
server fn preserved_file_effect(path:str) -> result<str> !{fs} { return file_read_text(path); }
server fn reader() -> (server fn(str)->result<str> !{fs}) { return preserved_file_effect; }
fn main() -> unit !{io} { print(identity(file_read_bytes(41)+bytes(0))); print(file_write_bytes("Я🧠")); }
test fn preserved_test() -> unit { assert(file_read_bytes(41)==42); assert(file_write_bytes("text")=="text"); assert(bytes(7)==7); }
